-- Legacy name strings are now resolved, so scenes that were only ever "pending
-- a pre-merge fix" count as resolved. A scene whose cast genuinely converted
-- to nothing keeps cast_resolved_at NULL and gets re-derived on the next build.
UPDATE "scenes" SET "cast_resolved_at" = now()
WHERE "cast_resolved_at" IS NULL
	AND EXISTS (SELECT 1 FROM "scene_characters" sc WHERE sc."scene_id" = "scenes"."id");
